@layer base, components, utilities;

@layer base {
  button { padding: 8px 12px; background: gray; }
}

@layer utilities {
  /* base より後のレイヤー → 詳細度に関係なく勝つ */
  .btn-primary { background: blue; }
}

@layer reset, vendor, base, components, utilities;

@import url('modern-normalize.css') layer(reset);
@import url('@my-ui/styles.css') layer(vendor);

@layer base {
  body { font-family: system-ui; }
}

@layer base, utilities;

@layer base {
  /* 通常宣言なら utilities に負ける */
  p { color: black; }
  /* important なら base のほうが utilities より強い */
  p { color: red !important; }
}
@layer utilities {
  p { color: green !important; }
}
/* 結果: 赤 (!important では base が逆転して強い) */

@layer reset, tokens, base, components, utilities;

@layer tokens {
  :root {
    --color-primary: #1cb0f6;
    --space-2: 8px;
  }
}

@layer base, components;

@layer components {
  .btn { background: blue; }
}

@layer base {
  #app .btn { background: red; }
}

@layer a, b;
@layer a { p { color: red !important; } }
@layer b { p { color: blue !important; } }

@layer a;
@layer a { h1 { color: red; } }
h1 { color: blue; } /* レイヤー外 */
